  local okAfk, afk = pcall(funcLuaMenuCommand, 2640875187 --[[CMND_IS_OPEN_LAYER]], EVT_RG_AFK, 0)
  if okAfk and afk == true then
    return
  end
  local okW, w = pcall(funcLuaMenuCommand, 1775716383, EVT_RG_LAYER, 0, true, true)
  if not okW or type(w) ~= "number" or w <= 0 then
    return
  end
  local x = math.floor(EVT_RG_HALF_W - EVT_RG_RIGHT_GAP - w + 0.5)
  -- written on every call: retail re-centres it on its own (stamp guide moves, OnOpenLayer), and the width follows
  -- the glyph of the active device
  pcall(funcLuaMenuCommand, 1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], EVT_RG_LAYER, x, EVT_RG_DY, 0, 0)
  local key = x .. "," .. EVT_RG_DY
  if key ~= evt_rg_last then
    evt_rg_last = key
    pcall(funcLuaCommand, 3661580131 --[[CMND_EVT_LOG]], "ui_clean retire guide", "width " .. tostring(w), "x " .. tostring(x))
  end
end

